-- ── hand-written: the guard of the two checks below ─────────────────────────────────────────────
-- Both checks read the whole company's plans or hierarchy, which the writer may not be allowed to
-- read, so before anything else they make sure the writer is this company's owner: otherwise
-- their answer ("dates overlap", "a circle") would tell a stranger what is there. They read what
-- is committed now, so a transaction that reads an older picture of the database (repeatable
-- read, serializable) is not let in: two of those could each miss the other's row and together
-- close a circle or overlap two plans. Two writers at once are taken one after the other by
-- locking the company's row, which the app's role cannot lock itself (it has no UPDATE on
-- tenants), so nobody can stall another company's saves. The database's own migrations, run as
-- postgres, are not held to the owner check. Found by this step's review (2026-11-15).
CREATE FUNCTION app.guard_commission_setup(p_tenant uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF session_user <> 'postgres' AND (p_tenant IS DISTINCT FROM app.tenant_id() OR app.tenant_role() IS DISTINCT FROM 'owner') THEN
    RAISE EXCEPTION 'only the owner sets up commission plans' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'commission plans are written in read committed transactions' USING ERRCODE = 'SE304';
  END IF;
  PERFORM 1 FROM public.tenants t WHERE t.id = p_tenant FOR NO KEY UPDATE;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.guard_commission_setup(uuid) FROM PUBLIC;
--> statement-breakpoint

-- ── hand-written: plans of one person never overlap ─────────────────────────────────────────────
-- Each person's plans, and the default plans (no person), cover separate stretches of time, so
-- that one plan applies to a sale. Ranges that only touch end to end are allowed. It reads
-- every plan of the company whoever writes, so it runs as the table's owner; every name in it is
-- written in full and its search path ends with the temporary schema (0023_safe_search_path).
CREATE FUNCTION app.check_commission_plan_dates() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  PERFORM app.guard_commission_setup(NEW.tenant_id);
  IF EXISTS (
    SELECT 1 FROM public.commission_plans p
    WHERE p.tenant_id = NEW.tenant_id AND p.id <> NEW.id AND p.user_id IS NOT DISTINCT FROM NEW.user_id
      AND (p.effective_to IS NULL OR NEW.effective_from <= p.effective_to)
      AND (NEW.effective_to IS NULL OR p.effective_from <= NEW.effective_to)
  ) THEN
    RAISE EXCEPTION 'Commission plan dates overlap.' USING ERRCODE = 'SE301';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_commission_plan_dates() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER commission_plans_dates
  BEFORE INSERT OR UPDATE OF user_id, effective_from, effective_to, tenant_id ON public.commission_plans
  FOR EACH ROW EXECUTE FUNCTION app.check_commission_plan_dates();
--> statement-breakpoint

-- ── hand-written: the hierarchy has no circles ──────────────────────────────────────────────────
-- Walking up from the new manager must never come back to the member. The guard above takes
-- two changes at once one after the other, so they cannot close a circle between them.
CREATE FUNCTION app.check_sales_hierarchy() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_at uuid := NEW.manager_user_id;
  v_steps integer := 0;
BEGIN
  PERFORM app.guard_commission_setup(NEW.tenant_id);
  LOOP
    IF v_at = NEW.user_id THEN
      RAISE EXCEPTION 'The sales hierarchy cannot contain a cycle.' USING ERRCODE = 'SE302';
    END IF;
    SELECT h.manager_user_id INTO v_at FROM public.sales_hierarchy h
      WHERE h.tenant_id = NEW.tenant_id AND h.user_id = v_at AND h.id <> NEW.id;
    EXIT WHEN NOT FOUND;
    v_steps := v_steps + 1;
    IF v_steps > 1000 THEN
      RAISE EXCEPTION 'The sales hierarchy cannot contain a cycle.' USING ERRCODE = 'SE302';
    END IF;
  END LOOP;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_sales_hierarchy() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER sales_hierarchy_no_cycle
  BEFORE INSERT OR UPDATE OF user_id, manager_user_id, tenant_id ON public.sales_hierarchy
  FOR EACH ROW EXECUTE FUNCTION app.check_sales_hierarchy();
--> statement-breakpoint

-- ── hand-written: what a sale earns, for Step 38 ────────────────────────────────────────────────
-- The same working-out as src/modules/commissions/rules.ts (commissionOnLine, slabs,
-- managerShare); the tests hold the two to the same figures. These run as the table's owner and
-- take the company as an argument, so they are not for the app's role: only other functions of
-- the database (Step 38's posting) call them. Each is revoked from PUBLIC and granted to nobody.

-- The plan that applies to a salesperson on a day: their own plan covering it, else the default
-- plan covering it, else none.
CREATE FUNCTION app.commission_plan_for(p_tenant uuid, p_user uuid, p_date date) RETURNS uuid
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT p.id FROM public.commission_plans p
    WHERE p.tenant_id = p_tenant AND p_date IS NOT NULL
      AND (p.user_id = p_user OR p.user_id IS NULL)
      AND p.effective_from <= p_date AND (p.effective_to IS NULL OR p.effective_to >= p_date)
    ORDER BY (p.user_id IS NULL), p.effective_from DESC
    LIMIT 1
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.commission_plan_for(uuid, uuid, date) FROM PUBLIC;
--> statement-breakpoint

-- What a tiered plan's slabs give on a month's sales of p_total: each slab's rate on the part of
-- the total inside it. Not rounded.
CREATE FUNCTION app.commission_slabs(p_plan uuid, p_total numeric) RETURNS numeric
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT coalesce(sum(GREATEST(0::numeric, LEAST(p_total, coalesce(s.next_threshold, p_total)) - s.threshold) * s.rate / 100), 0)
    FROM (
      SELECT t.threshold, t.rate, lead(t.threshold) OVER (ORDER BY t.threshold) AS next_threshold
      FROM public.commission_plan_tiers t WHERE t.plan_id = p_plan
    ) s
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.commission_slabs(uuid, numeric) FROM PUBLIC;
--> statement-breakpoint

-- What one salesperson earns on their part of an invoice line, rounded to four decimals:
--   p_base         their share of the line's value after discount, before tax (in base currency)
--   p_quantity     their share of the quantity, in the item's own unit
--   p_month_before what they had already sold in the same calendar month, before this line
-- No row when no plan applies on p_date. The plan's id comes back with the amount, so that
-- Step 38 can keep which plan an accrual was worked out on.
CREATE FUNCTION app.commission_on_line(p_tenant uuid, p_user uuid, p_date date, p_item uuid, p_customer uuid, p_base numeric, p_quantity numeric, p_month_before numeric)
  RETURNS TABLE (plan_id uuid, amount numeric)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_plan public.commission_plans%ROWTYPE;
  v_rate numeric;
  v_amount numeric;
BEGIN
  -- "Infinity" and "not a number" both sort at or above 'Infinity'.
  IF p_base IS NULL OR p_base < 0 OR p_base >= 'Infinity'::numeric OR p_quantity IS NULL OR p_quantity < 0 OR p_quantity >= 'Infinity'::numeric
     OR p_month_before IS NULL OR p_month_before < 0 OR p_month_before >= 'Infinity'::numeric THEN
    RAISE EXCEPTION 'a commission is worked out on amounts of nothing or more' USING ERRCODE = 'SE303';
  END IF;
  SELECT * INTO v_plan FROM public.commission_plans p WHERE p.tenant_id = p_tenant AND p.id = app.commission_plan_for(p_tenant, p_user, p_date);
  IF NOT FOUND THEN
    RETURN;
  END IF;
  IF v_plan.kind = 'per_unit' THEN
    v_amount := p_quantity * v_plan.rate;
  ELSIF v_plan.kind = 'tiered' THEN
    v_amount := app.commission_slabs(v_plan.id, p_month_before + p_base) - app.commission_slabs(v_plan.id, p_month_before);
  ELSE
    v_rate := v_plan.rate;
    IF v_plan.kind = 'category' THEN
      SELECT r.rate INTO v_rate FROM public.commission_plan_rates r
        JOIN public.items i ON i.tenant_id = r.tenant_id AND i.id = p_item AND i.category_id = r.category_id
        WHERE r.tenant_id = p_tenant AND r.plan_id = v_plan.id;
      v_rate := coalesce(v_rate, v_plan.rate);
    ELSIF v_plan.kind = 'customer_class' THEN
      SELECT r.rate INTO v_rate FROM public.commission_plan_rates r
        JOIN public.customers c ON c.tenant_id = r.tenant_id AND c.id = p_customer
          AND lower(btrim(c.customer_class)) = lower(btrim(r.customer_class))
        WHERE r.tenant_id = p_tenant AND r.plan_id = v_plan.id;
      v_rate := coalesce(v_rate, v_plan.rate);
    END IF;
    v_amount := p_base * v_rate / 100;
  END IF;
  IF v_plan.target > 0 AND p_month_before + p_base >= v_plan.target THEN
    v_amount := v_amount * v_plan.multiplier;
  END IF;
  plan_id := v_plan.id;
  amount := round(v_amount, 4);
  RETURN NEXT;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.commission_on_line(uuid, uuid, date, uuid, uuid, numeric, numeric, numeric) FROM PUBLIC;
--> statement-breakpoint

-- Everyone above a salesperson, nearest first (level 1 is their own manager), each with the plan
-- that applies to them on p_date and its team rate (0 when they have none). A manager earns
-- round(base × team_rate / 100, 4) on the seller's base (managerShare in rules.ts).
CREATE FUNCTION app.commission_managers(p_tenant uuid, p_user uuid, p_date date)
  RETURNS TABLE (level integer, manager_user_id uuid, plan_id uuid, team_rate numeric)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    WITH RECURSIVE up (level, user_id) AS (
      SELECT 1, h.manager_user_id FROM public.sales_hierarchy h WHERE h.tenant_id = p_tenant AND h.user_id = p_user
      UNION ALL
      SELECT up.level + 1, h.manager_user_id FROM up
      JOIN public.sales_hierarchy h ON h.tenant_id = p_tenant AND h.user_id = up.user_id
      WHERE up.level < 50
    )
    SELECT up.level, up.user_id, pl.id, coalesce(pl.team_rate, 0)
    FROM up
    LEFT JOIN public.commission_plans pl ON pl.tenant_id = p_tenant AND pl.id = app.commission_plan_for(p_tenant, up.user_id, p_date)
    WHERE up.user_id <> p_user
    ORDER BY up.level
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.commission_managers(uuid, uuid, date) FROM PUBLIC;
